import fs from "fs/promises";
import path from "path";
import {
  RECITERS_LIST,
  fillAyahAudioTemplate,
  getAyahLocation,
  getJuzAyahRange,
  type Reciter,
} from "@/lib/quranStream";

// ─── Types ────────────────────────────────────────────────────────────────────

/**
 * Per-ayah audio entry generated by `scripts/generateAudioMetadata.mjs`:
 * [first audio byte in the file, audio byte length, duration in ms, format code (default 0)].
 * Tags and the Xing/Info frame are excluded, so ayahs concatenate into a clean MP3 stream.
 */
type AyahAudioTuple = [number, number, number] | [number, number, number, number];

interface ReciterAudioData {
  /** Distinct sample-rate/channel formats; index 0 is the reciter's main format. */
  formats: string[];
  /** Indexed by global ayah number - 1. */
  ayahs: AyahAudioTuple[];
  /** Ayahs served from an alternate source, keyed by global ayah number. */
  urls?: Record<string, string>;
}

interface AudioMetadataFile {
  version: string;
  reciters: Record<string, ReciterAudioData>;
}

export interface AyahSlice {
  ayahNumber: number;
  surahNumber: number;
  numberInSurah: number;
  url: string;
  /** Byte offset of the ayah's audio frames inside its source file. */
  fileStart: number;
  length: number;
  /** Byte offset of this ayah inside its segment stream. */
  streamStart: number;
  /** Seconds from the start of the Juz. */
  startSec: number;
  duration: number;
}

/**
 * A run of ayahs that share one audio format and are streamed as one continuous MP3.
 * Most Juz are a single segment; a Juz is split only where the source audio changes format.
 */
export interface JuzSegment {
  index: number;
  totalSize: number;
  startSec: number;
  duration: number;
  ayahs: AyahSlice[];
}

export interface JuzAudioMap {
  juz: number;
  reciter: Reciter;
  version: string;
  totalDuration: number;
  segments: JuzSegment[];
}

export interface StreamSlice {
  url: string;
  /** First byte to read from the source file. */
  fileStart: number;
  /** Exact number of bytes this slice contributes to the response. */
  length: number;
}

// ─── Metadata ────────────────────────────────────────────────────────────────

let metadataPromise: Promise<AudioMetadataFile> | null = null;
const juzMapCache = new Map<string, JuzAudioMap>();

/** Loads the generated audio metadata once per server instance. */
function loadAudioMetadata(): Promise<AudioMetadataFile> {
  metadataPromise ??= fs
    .readFile(path.join(process.cwd(), "src/data/audioMetadata.json"), "utf-8")
    .then((raw) => JSON.parse(raw) as AudioMetadataFile)
    .catch((err: unknown) => {
      metadataPromise = null; // Allow a later request to retry.
      throw err;
    });
  return metadataPromise;
}

/**
 * Resolves the Reciter by ID or fallback
 */
export function resolveReciter(reciterParam?: string | number | null): Reciter {
  if (!reciterParam) return RECITERS_LIST[0];

  const parsedId = typeof reciterParam === "number" ? reciterParam : parseInt(reciterParam, 10);
  if (!isNaN(parsedId)) {
    const found = RECITERS_LIST.find((r) => r.id === parsedId);
    if (found) return found;
  }

  if (typeof reciterParam === "string") {
    const lower = reciterParam.toLowerCase();
    const found = RECITERS_LIST.find((r) => r.name.toLowerCase().includes(lower));
    if (found) return found;
  }

  return RECITERS_LIST[0];
}

/** Clamps a `juz` query parameter to 1–30. */
export function parseJuzParam(value: string | null): number {
  const parsed = parseInt(value || "1", 10);
  return Math.max(1, Math.min(30, isNaN(parsed) ? 1 : parsed));
}

/**
 * Builds the byte and time layout of a Juz for one reciter, split into format-uniform segments.
 * Returns null when no audio metadata exists for the reciter.
 */
export async function getJuzAudioMap(juz: number, reciter: Reciter): Promise<JuzAudioMap | null> {
  const cacheKey = `${juz}_${reciter.id}`;
  const cachedMap = juzMapCache.get(cacheKey);
  if (cachedMap) return cachedMap;

  const metadata = await loadAudioMetadata();
  const data = metadata.reciters[reciter.id];
  if (!data) return null;

  const [firstAyah, lastAyah] = getJuzAyahRange(juz);
  const segments: JuzSegment[] = [];
  let current: JuzSegment | null = null;
  let currentFormat = -1;
  let elapsed = 0;

  for (let ayahNumber = firstAyah; ayahNumber <= lastAyah; ayahNumber++) {
    const [fileStart, length, durationMs, format = 0] = data.ayahs[ayahNumber - 1];
    if (length <= 0) continue; // Unplayable at every known source.

    if (!current || format !== currentFormat) {
      current = { index: segments.length, totalSize: 0, startSec: elapsed, duration: 0, ayahs: [] };
      currentFormat = format;
      segments.push(current);
    }

    const { surah, verse } = getAyahLocation(ayahNumber);
    const duration = durationMs / 1000;
    current.ayahs.push({
      ayahNumber,
      surahNumber: surah,
      numberInSurah: verse,
      url: data.urls?.[ayahNumber] ?? fillAyahAudioTemplate(reciter.ayahAudioTemplate, ayahNumber),
      fileStart,
      length,
      streamStart: current.totalSize,
      startSec: elapsed,
      duration,
    });
    current.totalSize += length;
    current.duration += duration;
    elapsed += duration;
  }

  if (segments.length === 0) return null;

  const map: JuzAudioMap = {
    juz,
    reciter,
    version: metadata.version,
    totalDuration: elapsed,
    segments,
  };
  juzMapCache.set(cacheKey, map);
  return map;
}

/** Public URL of one segment stream; the version busts caches when the metadata changes. */
export function getSegmentStreamUrl(map: JuzAudioMap, segmentIndex: number): string {
  return `/api/juz-stream?juz=${map.juz}&reciter=${map.reciter.id}&segment=${segmentIndex}&v=${map.version}`;
}

/** Maps an inclusive byte range of a segment stream onto source-file slices. */
export function getStreamSlicesForRange(
  segment: JuzSegment,
  start: number,
  end: number
): StreamSlice[] {
  const slices: StreamSlice[] = [];
  for (const ayah of segment.ayahs) {
    const ayahEnd = ayah.streamStart + ayah.length - 1;
    if (ayahEnd < start || ayah.streamStart > end) continue;
    const from = Math.max(start, ayah.streamStart) - ayah.streamStart;
    const to = Math.min(end, ayahEnd) - ayah.streamStart;
    slices.push({ url: ayah.url, fileStart: ayah.fileStart + from, length: to - from + 1 });
  }
  return slices;
}

// ─── Resilient Stream Pipe ────────────────────────────────────────────────────

const UPSTREAM_HEADERS_TIMEOUT_MS = 15000;
const UPSTREAM_ATTEMPTS = 3;
const PADDING_CHUNK = 16 * 1024;

interface UpstreamBody {
  reader: ReadableStreamDefaultReader<Uint8Array>;
  /** Leading bytes to discard (the CDN ignored our Range header). */
  skip: number;
}

/** Requests bytes [fileStart, fileStart + length) of a source file, retrying transient failures. */
async function openUpstream(
  url: string,
  fileStart: number,
  length: number,
  signal: AbortSignal
): Promise<UpstreamBody | null> {
  for (let attempt = 1; attempt <= UPSTREAM_ATTEMPTS && !signal.aborted; attempt++) {
    const controller = new AbortController();
    const onAbort = () => controller.abort();
    signal.addEventListener("abort", onAbort, { once: true });
    const timer = setTimeout(() => controller.abort(), UPSTREAM_HEADERS_TIMEOUT_MS);
    try {
      const res = await fetch(url, {
        headers: { Range: `bytes=${fileStart}-${fileStart + length - 1}` },
        signal: controller.signal,
      });
      if (res.body && (res.status === 206 || res.status === 200)) {
        return { reader: res.body.getReader(), skip: res.status === 200 ? fileStart : 0 };
      }
      await res.body?.cancel();
      if (res.status < 500) break; // 4xx will not succeed on retry.
    } catch {
      // Network error or timeout; retry below.
    } finally {
      clearTimeout(timer);
      signal.removeEventListener("abort", onAbort);
    }
  }
  if (!signal.aborted) {
    console.warn(`[streamServer] Upstream unavailable, padding ${length} bytes: ${url}`);
  }
  return null;
}

/**
 * Pipes the slices into one byte stream of exactly the summed slice lengths.
 *
 * Bytes are pulled from the CDN only as fast as the client reads them, the next slice is
 * requested ahead of time to hide CDN latency, and a slice the CDN cannot deliver is padded
 * with zero bytes (skipped by MP3 decoders) so `Content-Length` and later offsets stay exact.
 */
export function createMultiAudioStream(
  slices: StreamSlice[],
  signal?: AbortSignal
): ReadableStream<Uint8Array> {
  const abort = new AbortController();
  if (signal?.aborted) abort.abort();
  signal?.addEventListener("abort", () => abort.abort(), { once: true });

  const pending = new Map<number, Promise<UpstreamBody | null>>();
  const request = (index: number, offset = 0): Promise<UpstreamBody | null> => {
    const slice = slices[index];
    return openUpstream(slice.url, slice.fileStart + offset, slice.length - offset, abort.signal);
  };
  const prefetch = (index: number) => {
    if (index < slices.length && !pending.has(index)) pending.set(index, request(index));
  };

  let index = -1;
  let delivered = 0; // Bytes of the current slice already sent.
  let body: UpstreamBody | null = null;
  let reopened = false;

  const release = () => {
    body?.reader.cancel().catch(() => {});
    body = null;
  };

  return new ReadableStream<Uint8Array>(
    {
      async pull(controller) {
        while (!abort.signal.aborted) {
          const slice = slices[index];
          if (index < 0 || delivered >= slice.length) {
            release();
            index++;
            if (index >= slices.length) {
              controller.close();
              return;
            }
            prefetch(index);
            body = await pending.get(index)!;
            pending.delete(index);
            delivered = 0;
            reopened = false;
            prefetch(index + 1);
            continue;
          }

          const remaining = slice.length - delivered;
          if (!body) {
            const padding = Math.min(remaining, PADDING_CHUNK);
            delivered += padding;
            controller.enqueue(new Uint8Array(padding));
            return;
          }

          let chunk: Uint8Array | undefined;
          try {
            const result = await body.reader.read();
            chunk = result.done ? undefined : result.value;
          } catch {
            chunk = undefined;
          }

          if (!chunk) {
            // Upstream ended early: resume once from the current offset, then pad.
            release();
            if (!reopened) {
              reopened = true;
              body = await request(index, delivered);
            }
            continue;
          }

          if (body.skip > 0) {
            const dropped = Math.min(body.skip, chunk.length);
            body.skip -= dropped;
            chunk = chunk.subarray(dropped);
            if (chunk.length === 0) continue;
          }
          if (chunk.length > remaining) chunk = chunk.subarray(0, remaining);
          delivered += chunk.length;
          controller.enqueue(chunk);
          return;
        }
      },
      cancel() {
        abort.abort();
        release();
        pending.forEach((p) => p.then((b) => b?.reader.cancel().catch(() => {})));
        pending.clear();
      },
    },
    { highWaterMark: 0 }
  );
}
